s=s[:at]+'''/// The authenticated immediate peer category at the first retained network ingress.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ReceivedVia {
    Sender,
    Member,
    PostOffice,
    LinkedDevice,
}
impl ReceivedVia {
    fn tag(self) -> i64 {
        match self { Self::Sender => 1, Self::Member => 2, Self::PostOffice => 3, Self::LinkedDevice => 4 }
    }
    fn from_tag(tag: i64) -> Result<Self, LogError> {
        match tag { 1 => Ok(Self::Sender), 2 => Ok(Self::Member), 3 => Ok(Self::PostOffice), 4 => Ok(Self::LinkedDevice), _ => Err(invalid("invalid ingress origin")) }
    }
}

pub(crate) struct IngressOrigin {
    pub via: ReceivedVia,
    pub peer_device: String,
}

const SCHEMA: &str = "
CREATE TABLE pending_ingress_origins(account BLOB NOT NULL CHECK(length(account)=32), domain BLOB NOT NULL CHECK(length(domain)=16), event_id BLOB NOT NULL CHECK(length(event_id)=32), conversation BLOB NOT NULL CHECK(length(conversation)=32), via INTEGER NOT NULL CHECK(via BETWEEN 1 AND 4), peer_device TEXT NOT NULL CHECK(length(peer_device)=32), PRIMARY KEY(account,domain,event_id), FOREIGN KEY(domain,event_id) REFERENCES retained_events(domain,id) ON DELETE CASCADE);
CREATE INDEX pending_ingress_source ON pending_ingress_origins(account,conversation,event_id);
CREATE TABLE transcript_ingress_origins(ordinal INTEGER PRIMARY KEY REFERENCES transcript_rows(ordinal) ON DELETE CASCADE, account BLOB NOT NULL CHECK(length(account)=32), via INTEGER NOT NULL CHECK(via BETWEEN 1 AND 4), peer_device TEXT NOT NULL CHECK(length(peer_device)=32));
";

pub(super) fn initialize_on(c: &Connection) -> Result<(), LogError> {
    let present: i64 = c.query_row("SELECT count(*) FROM sqlite_master WHERE name IN ('pending_ingress_origins','pending_ingress_source','transcript_ingress_origins')", [], |r| r.get(0))?;
    if present == 0 { c.execute_batch(SCHEMA)?; }
    else if present != 3 { return Err(invalid("incomplete ingress origin schema")); }
    manifest::validate_ddl(c, SCHEMA)
}

impl ReceptionEffects {
    /// The caller holds the raw append transaction. Never reacquire the database.
    pub(crate) fn record_origin_on(&self, c: &Connection, domain: EventDomainId, event: &Event, origin: &IngressOrigin) -> Result<(), LogError> {
        self.state_on(c)?;
        if origin.peer_device.len() != 32 || !origin.peer_device.bytes().all(|b| b.is_ascii_hexdigit()) {
            return Err(invalid("invalid ingress peer device"));
        }
        c.execute("INSERT INTO pending_ingress_origins(account,domain,event_id,conversation,via,peer_device) VALUES(?1,?2,?3,?4,?5,?6) ON CONFLICT(account,domain,event_id) DO NOTHING", params![self.account.as_slice(),domain.0.as_slice(),event.id.as_bytes().as_slice(),event.conversation_id.as_bytes().as_slice(),origin.via.tag(),origin.peer_device])?;
        Ok(())
    }

    pub(crate) fn received_via(&self, conversation: ConversationId, id: EventId) -> Result<Option<ReceivedVia>, LogError> {
        self.profile.database().read(|c| {
            self.state_on(c)?;
            // Select the first source row BEFORE joining evidence. An unknown old
            // alias must not acquire a later alias's known ingress.
            let tag: Option<Option<i64>> = c.query_row("SELECT o.via FROM transcript_rows t LEFT JOIN transcript_ingress_origins o ON o.ordinal=t.ordinal AND o.account=?1 WHERE t.kind IN (2,3) AND t.conversation=?2 AND (t.row_key=?3 OR t.logical_id=?3) ORDER BY t.ordinal LIMIT 1", params![self.account.as_slice(),conversation.as_bytes().as_slice(),id.as_bytes().as_slice()], |r| r.get(0)).optional()?;
            tag.flatten().map(ReceivedVia::from_tag).transpose()
        })
    }
}

/// Migrate evidence only for a new reception, in the existing transcript commit.
pub(super) fn project_on(c: &Connection, account: &[u8;32], source: ReceptionSource) -> Result<(), LogError> {
    c.execute("INSERT INTO transcript_ingress_origins(ordinal,account,via,peer_device) SELECT t.ordinal,p.account,p.via,p.peer_device FROM transcript_rows t JOIN pending_ingress_origins p ON p.account=?1 AND p.conversation=t.conversation AND p.event_id=t.row_key WHERE t.kind=?2 AND t.conversation=?3 AND t.row_key=?4 ORDER BY p.domain LIMIT 1 ON CONFLICT(ordinal) DO NOTHING", params![account.as_slice(), source.kind.transcript_kind(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice()])?;
    c.execute("DELETE FROM pending_ingress_origins WHERE account=?1 AND conversation=?2 AND event_id=?3", params![account.as_slice(),source.conversation.as_bytes().as_slice(),source.event_id.as_bytes().as_slice()])?;
    Ok(())
}

