p='crates/mesh-talk-core/src/node/reception_effects/origins.rs';s=open(p).read();s += '''
#[cfg(test)]
mod projection_tests {
    use super::*;
    fn database() -> Connection {
        let c = Connection::open_in_memory().unwrap();
        c.execute_batch("PRAGMA foreign_keys=ON; CREATE TABLE retained_events(domain BLOB,id BLOB,PRIMARY KEY(domain,id)); CREATE TABLE transcript_rows(ordinal INTEGER PRIMARY KEY,kind INTEGER,conversation BLOB,row_key BLOB,logical_id BLOB);").unwrap();
        initialize_on(&c).unwrap();
        c
    }
    fn source() -> ReceptionSource {
        ReceptionSource { kind: ReceptionKind::DirectMessage, conversation: ConversationId::new([2;32]), event_id: EventId::new([3;32]) }
    }
    fn pending(c: &Connection) {
        c.execute("INSERT INTO retained_events VALUES(?1,?2)",params![[1u8;16].as_slice(),[3u8;32].as_slice()]).unwrap();
        c.execute("INSERT INTO pending_ingress_origins VALUES(?1,?2,?3,?4,3,?5)",params![[4u8;32].as_slice(),[1u8;16].as_slice(),[3u8;32].as_slice(),[2u8;32].as_slice(),"0123456789abcdef0123456789abcdef"]).unwrap();
    }
    fn transcript(c: &Connection) {
        c.execute("INSERT INTO transcript_rows VALUES(1,2,?1,?2,NULL)",params![[2u8;32].as_slice(),[3u8;32].as_slice()]).unwrap();
    }
    fn count(c: &Connection, table: &str) -> i64 {
        c.query_row(&format!("SELECT count(*) FROM {table}"), [], |r|r.get(0)).unwrap()
    }
    #[test]
    fn origin_projection_rolls_back_with_receipt_and_cascades_with_source() {
        let c = database(); pending(&c);
        c.execute_batch("BEGIN").unwrap();
        transcript(&c);
        project_on(&c,&[4;32],source()).unwrap();
        assert_eq!(count(&c,"pending_ingress_origins"),0);
        assert_eq!(count(&c,"transcript_ingress_origins"),1);
        c.execute_batch("ROLLBACK").unwrap();
        assert_eq!(count(&c,"pending_ingress_origins"),1);
        assert_eq!(count(&c,"transcript_ingress_origins"),0);
        transcript(&c);
        project_on(&c,&[4;32],source()).unwrap();
        // A duplicate installation cannot overwrite the first origin.
        c.execute("INSERT INTO pending_ingress_origins VALUES(?1,?2,?3,?4,1,?5)",params![[4u8;32].as_slice(),[1u8;16].as_slice(),[3u8;32].as_slice(),[2u8;32].as_slice(),"0123456789abcdef0123456789abcdef"]).unwrap();
        project_on(&c,&[4;32],source()).unwrap();
        assert_eq!(c.query_row("SELECT via FROM transcript_ingress_origins",[],|r|r.get::<_,i64>(0)).unwrap(),3);
        c.execute("DELETE FROM transcript_rows",[]).unwrap();
        assert_eq!(count(&c,"transcript_ingress_origins"),0);
    }
    #[test]
    fn absent_legacy_evidence_stays_unknown_and_other_accounts_do_not_project() {
        let c = database(); transcript(&c);
        project_on(&c,&[4;32],source()).unwrap();
        assert_eq!(count(&c,"transcript_ingress_origins"),0);
        pending(&c);
        project_on(&c,&[5;32],source()).unwrap();
        assert_eq!(count(&c,"transcript_ingress_origins"),0);
        assert_eq!(count(&c,"pending_ingress_origins"),1);
        c.execute("DELETE FROM retained_events",[]).unwrap();
        assert_eq!(count(&c,"pending_ingress_origins"),0);
    }
}
''';open(p,'w').write(s)
