#[cfg(test)]
mod owner_tests {
    use super::*;
    use crate::identity::{account::Account, device::DeviceIdentity};
    use crate::storage::profile::ProfileStorageLease;
    use crate::eventlog::{EventKind, persist::PersistentEventLog};

    #[test]
    fn first_authenticated_origin_survives_reopen_and_owner_replacement_fences_writer() {
        let dir = tempfile::tempdir().unwrap();
        let device = DeviceIdentity::generate();
        let account = Account::generate();
        let open = || {
            let p = ProfileStorage::open_participant(ProfileStorageLease::acquire(dir.path()).unwrap(), &device.public(), &account.public(), &dir.path().join("messages.log"), &dir.path().join("sent.log"), "pw").unwrap();
            p.complete_participant("pw",None).unwrap();
            p
        };
        let profile = open();
        let mut log = PersistentEventLog::open_profile(profile.clone(),"pw").unwrap();
        let effects = ReceptionEffects::open(profile.clone()).unwrap();
        let event = Event::new(&device,ConversationId::new([8;32]),1,vec![],1,1,EventKind::Message,vec![]);
        let origin = IngressOrigin {via:ReceivedVia::PostOffice,peer_device:device.public().user_id()};
        log.append_durable_observed(event.clone(),|c,d,e|effects.record_origin_on(c,d,e,&origin)).unwrap();
        let changed = IngressOrigin {via:ReceivedVia::Sender,peer_device:device.public().user_id()};
        log.append_durable_observed(event.clone(),|c,d,e|effects.record_origin_on(c,d,e,&changed)).unwrap();
        let source = ReceptionSource {kind:ReceptionKind::DirectMessage,conversation:event.conversation_id,event_id:event.id};
        profile.database().transaction(|c| {
            super::super::super::transcript_repository::TranscriptRepository::put_on(c,2,source.conversation,source.event_id.as_bytes(),1,0,"peer",b"body",false,false)?;
            let metadata = ReceptionMetadata {from_device:device.public().user_id(),received_at:1,arrival_kind:ArrivalKind::Live,own_device:false,batch_id:None,batch_complete:true,batch_size:1,reception_only:false};
            install_on(c,source,&metadata)?;
            Ok(())
        }).unwrap();
        assert_eq!(effects.received_via(source.conversation,source.event_id).unwrap(),Some(ReceivedVia::PostOffice));
        drop(log); drop(effects); drop(profile);
        let profile = open();
        let effects = ReceptionEffects::open(profile.clone()).unwrap();
        assert_eq!(effects.received_via(source.conversation,source.event_id).unwrap(),Some(ReceivedVia::PostOffice));
        let next = Account::generate();
        crate::storage::profile::participant::prepare_adoption(profile.database(),&account.public(),&next.public()).unwrap();
        crate::storage::profile::participant::finish_adoption(profile.database(),&next.public()).unwrap();
        assert!(matches!(effects.received_via(source.conversation,source.event_id),Err(LogError::StaleCursor)));
        let rejected = profile.database().transaction(|c|effects.record_origin_on(c,EventDomainId([0;16]),&event,&changed));
        assert!(matches!(rejected,Err(LogError::StaleCursor)));
    }
}
